import csv,hashlib,io,json,sqlite3,zipfile
from fractions import Fraction
from datetime import datetime,timezone
from pathlib import Path
import pyarrow.parquet as pq
ROOT=Path('/home/lars/Crypto_Multifactor_Bot');OUT=Path('/tmp/cex002_closeout530')
selected=json.loads((OUT/'selected.json').read_text());pins=[];examples=[];summaries=[]
def verified(path,sha,size=None):
 p=ROOT/path;assert p.is_file() and not p.is_symlink(),p
 b=p.read_bytes();assert hashlib.sha256(b).hexdigest()==sha,p
 if size is not None:assert len(b)==size,(p,len(b),size)
 pins.append({'path':str(path),'sha256':sha,'bytes':len(b)});return b
pubsha='5ea22270b71064c94c4f6dc60f3f045219742a3130cfdb1293b6cbe47a99a30d';pub=json.loads(verified(Path('data/.cex002_harmonic_bundle/.publication')/(pubsha+'.json'),pubsha));manifest_files={}
for kind,product in [('oi','binance_usdm_open_interest_5m'),('funding','binance_usdm_funding_realized')]:
 entry=next(e for e in pub['datasets'] if e['dataset_type']==product);m=json.loads(verified(entry['manifest_relative_path'],entry['manifest_file_sha256'],entry['manifest_bytes']));manifest_files[kind]={f['relative_path']:f for f in m['files']}
con=sqlite3.connect(f'file:{ROOT}/data/cex002_qualify/gate2/state.sqlite?mode=ro',uri=True);con.row_factory=sqlite3.Row
raw_cache={}
def source_rows(source):
 sha=source['source_sha256']
 if sha in raw_cache:return raw_cache[sha]
 matches=con.execute('SELECT * FROM completion WHERE content_sha256=?',(sha,)).fetchall();assert len(matches)==1
 c=dict(matches[0]);assert c['validation_state']=='checksum_verified';assert c['listed_bytes']==source['byte_size'];path=Path(c['content_path']);assert path==Path('data/cex002_qualify/gate2/content')/sha[:2]/sha
 b=verified(path,sha,source['byte_size']);side=verified(c['sidecar_path'],c['sidecar_sha256']);line=side.decode().strip().split();assert line[0]==sha and line[1].lstrip('*')==source['source_key'].split('/')[-1]
 with zipfile.ZipFile(io.BytesIO(b)) as z:
  ns=z.namelist();expected=source['source_key'].rsplit('/',1)[-1][:-4]+'.csv';assert ns==[expected];info=z.getinfo(expected);assert info.file_size<=2*1024*1024
  data=z.read(expected);assert len(data)==info.file_size
 rows=list(csv.DictReader(io.StringIO(data.decode('utf-8-sig'))));assert rows
 raw_cache[sha]=(rows,{'source_key':source['source_key'],'source_sha256':sha,'raw_path':str(path),'zip_member':expected,'uncompressed_bytes':len(data),'sidecar_sha256':c['sidecar_sha256'],'source_available_at':source['source_available_at'],'retrieval_time':source['retrieval_time']});return raw_cache[sha]
def raw_for(row,lineage,kind):
 source=next(s for s in lineage['raw_objects'] if s['raw_object_ref']==row['raw_object_ref']);rows,info=source_rows(source);ordinal=row['source_row_ordinal'];raw=rows[ordinal]
 if kind=='oi':
  stamp=int(datetime.fromisoformat(raw['create_time']).replace(tzinfo=timezone.utc).timestamp()*1000);assert stamp==row['create_time'];assert raw['symbol']==row['native_symbol']
  for field in ['sum_open_interest','sum_open_interest_value']:assert Fraction(raw[field])==Fraction(row[field]),field
 else:
  assert int(raw['calc_time'])==row['calc_time'];assert int(raw['funding_interval_hours'])==row['funding_interval_hours'];assert Fraction(raw['last_funding_rate'])==Fraction(row['last_funding_rate'])
 return {'source_row_ordinal':ordinal,'raw_fields':raw,'source':info}
for item in selected:
 kind=item['kind'];root=Path(item['root']);p=item['partition'];m=manifest_files[kind]
 for path_key,sha_key in [('parquet_path','parquet_sha256'),('lineage_path','lineage_sha256')]:
  path=root/p[path_key];entry=m[str(path)];assert entry['sha256']==p[sha_key];verified(path,p[sha_key],entry['bytes'])
 lineage=json.loads((ROOT/root/p['lineage_path']).read_text());assert lineage['parquet_sha256']==p['parquet_sha256'];pf=pq.ParquetFile(ROOT/root/p['parquet_path']);assert pf.metadata.num_rows==p['row_count'];rows=pf.read().to_pylist()
 summary={'kind':kind,'symbol':p['native_symbol'],'month':p['utc_month'],'rows':len(rows),'partition':p,'schema':str(pf.schema_arrow)}
 if kind=='oi':
  for before,after in zip(rows,rows[1:]):
   if after['create_time']-before['create_time']!=300000:continue
   old=raw_for(before,lineage,kind);new=raw_for(after,lineage,kind)
   assert after['change_interval_seconds']==300 and after['gap_break_status']=='contiguous'
   assert Fraction(after['previous_sum_open_interest'])==Fraction(before['sum_open_interest'])
   eq={}
   for level,change in [('sum_open_interest','open_interest_change'),('sum_open_interest_value','open_interest_value_change')]:
    difference=Fraction(new['raw_fields'][level])-Fraction(old['raw_fields'][level]);assert difference==Fraction(after[change]);eq[change]={'source_before':old['raw_fields'][level],'source_after':new['raw_fields'][level],'exact_fraction_difference':str(difference),'normalized_difference':str(after[change])}
   examples.append({'kind':'oi_contiguous','symbol':p['native_symbol'],'month':p['utc_month'],'before_time':before['create_time'],'after_time':after['create_time'],'source_before':old,'source_after':new,'normalized_before':before,'normalized_after':after,'equations':eq,'units':{'sum_open_interest':'BTC base-asset quantity','sum_open_interest_value':'provider-reported USDT quote notional'}});break
  else:raise AssertionError('No contiguous example')
  gaps=[(i,row) for i,row in enumerate(rows) if i and row['create_time']-rows[i-1]['create_time']!=300000]
  if gaps:
   i,row=gaps[0];prev=rows[i-1];raw=raw_for(row,lineage,kind)
   assert row['open_interest_change'] is None and row['open_interest_value_change'] is None and row['previous_sum_open_interest'] is None
   examples.append({'kind':'oi_gap_break','month':p['utc_month'],'previous_time':prev['create_time'],'time':row['create_time'],'elapsed_seconds':(row['create_time']-prev['create_time'])//1000,'raw':raw,'normalized':row})
  summary['gap_breaks_in_partition']=len(gaps)
 else:
  signs={('negative' if Fraction(row['last_funding_rate'])<0 else 'positive' if Fraction(row['last_funding_rate'])>0 else 'zero') for row in rows};summary['observed_signs']=sorted(signs)
  for sign in ['negative','positive']:
   matched=next((row for row in rows if (Fraction(row['last_funding_rate'])<0 if sign=='negative' else Fraction(row['last_funding_rate'])>0)),None)
   if matched is None:continue
   raw=raw_for(matched,lineage,kind);rate=Fraction(raw['raw_fields']['last_funding_rate']);long=Fraction(matched['long_cashflow_rate']);short=Fraction(matched['short_cashflow_rate']);assert long==-rate and short==rate and long+short==0
   examples.append({'kind':'funding_sign','month':p['utc_month'],'sign':sign,'raw':raw,'normalized':matched,'equations':{'long_equals_negative_source_rate':True,'short_equals_source_rate':True,'sum_fraction':str(long+short)},'units':'dimensionless rate per reported settlement event; no position or payment entitlement inferred'})
 summaries.append(summary)
assert len(examples)<=12 and len(summaries)==6
out={'ticket':'CEX-002','review':530,'status':'PASS','command':'.venv/bin/python /tmp/cex002_closeout530/verify.py','selection':'BTCUSDT earliest, median-index and latest nonempty month in each accepted completion descriptor','partitions':summaries,'examples':examples,'authenticated_files':list({p['path']:p for p in pins}.values()),'raw_zip_objects':len(raw_cache),'example_count':len(examples),'scope':'six selected partitions, independent Fraction arithmetic, no normalizer arithmetic helpers','limitations':['OI notional preserves the provider-reported quote stock; this does not independently prove the venue valuation method.','Funding signs describe rates; no account position, payment entitlement or historical receipt time is inferred.']}
(OUT/'economic.json').write_text(json.dumps(out,indent=2,default=str)+'\n');print(json.dumps({'status':'PASS','partitions':len(summaries),'examples':len(examples),'raw_zip_objects':len(raw_cache),'funding_signs':[s.get('observed_signs') for s in summaries if s['kind']=='funding'],'gap_counts':[s.get('gap_breaks_in_partition') for s in summaries if s['kind']=='oi']}))
